import React, { useState, useRef, useEffect } from 'react';
import { GlobalStyles, Modal, Btn, ToastContainer } from './components/UI';
import useStore from './utils/useStore';
import useAuth from './utils/useAuth';
import { LoginScreen } from './components/Auth';
import Hub from './components/Hub';
import Dashboard from './components/Dashboard';
import Produits from './components/Produits';
import Mouvements from './components/Mouvements';
import Commandes from './components/Commandes';
import { Alertes, Fournisseurs, Clients, Rapports, Analyses, AuditLogs } from './components/Pages';
import { Lots, HistoriquePrix } from './components/Tracabilite';
import Facturation from './components/Facturation';
import Scanner from './components/Scanner';
import Parametres from './components/Parametres';



export default function App() {
  const [theme,    setTheme]    = useState(() => localStorage.getItem('ssc_theme') || 'light');
  const [page,     setPage]     = useState('hub');


  // Avatar Dropdown & Password Reset States
  const [profileOpen,   setProfileOpen]   = useState(false);
  const [pwdModalOpen,  setPwdModalOpen]  = useState(false);
  const [pwdMsg,        setPwdMsg]        = useState(null);
  const profileRef = useRef(null);

  const store = useStore();
  const auth  = useAuth();

  useEffect(() => {
    localStorage.setItem('ssc_theme', theme);
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);

  // Click outside to close profile dropdown
  useEffect(() => {
    const handleClick = (e) => {
      if (profileRef.current && !profileRef.current.contains(e.target)) {
        setProfileOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClick);
    return () => document.removeEventListener('mousedown', handleClick);
  }, []);

  const alertCount = store.alertes?.length || 0;


  // ÔöÇÔöÇ Auth Loading ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (auth.loading) return (
    <>
      <GlobalStyles />
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-page)', flexDirection: 'column', gap: 20 }}>
        <div style={{ fontFamily: 'Inter, sans-serif', fontWeight: 800, fontSize: '1.8rem', color: 'var(--text-main)', letterSpacing: '-0.02em' }}>SSC Flow</div>
        <div style={{ width: 36, height: 36, border: '3px solid var(--border-color)', borderTop: '3px solid var(--primary)', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    </>
  );

  // ÔöÇÔöÇ Not logged in ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (!auth.user) return <LoginScreen auth={auth} />;

  // ÔöÇÔöÇ Firebase loading ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ
  if (store.loading) return (
    <>
      <GlobalStyles />
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-page)', flexDirection: 'column', gap: 16 }}>
        <div style={{ fontFamily: 'Inter, sans-serif', fontWeight: 700, fontSize: '1.3rem', color: 'var(--text-main)' }}>Chargement des donn├®es...</div>
        <div style={{ width: 36, height: 36, border: '3px solid var(--border-color)', borderTop: '3px solid var(--primary)', borderRadius: '50%', animation: 'spin 0.8s linear infinite' }} />
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    </>
  );

  if (store.error) return (
    <>
      <GlobalStyles />
      <div style={{ minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', background: 'var(--bg-page)', flexDirection: 'column', gap: 16, padding: 32 }}>
        <div style={{ fontSize: '3rem' }}>ÔÜá´©Å</div>
        <div style={{ fontFamily: 'Inter, sans-serif', fontWeight: 800, fontSize: '1.4rem', color: '#ef4444' }}>Erreur Firebase</div>
        <div style={{ background: 'var(--bg-card)', borderRadius: 16, padding: '20px 28px', maxWidth: 500, border: '1px solid rgba(239,68,68,0.2)', fontSize: '0.875rem', color: 'var(--text-main)', lineHeight: 1.8, boxShadow: 'var(--card-shadow)' }}>
          {store.error}<br /><br />
          Ouvrez <code style={{ background: 'var(--input-bg)', padding: '2px 6px', borderRadius: 4 }}>src/firebase.js</code> et remplacez les valeurs VOTRE_... par celles de votre projet Firebase.
        </div>
      </div>
    </>
  );

  return (
    <>
      <GlobalStyles />
      <ToastContainer />
      <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column' }}>

        {/* ÔòÉÔòÉÔòÉ ANIMATED BACKGROUND ÔòÉÔòÉÔòÉ */}
        <div className="bg-animated" />
        <div className="radial-overlay" />

        {/* ÔòÉÔòÉÔòÉ TOP NAV ÔÇö Simplified ÔòÉÔòÉÔòÉ */}
        <header style={{ position: 'sticky', top: 0, zIndex: 50, padding: '16px 24px', background: 'var(--bg-page-solid)', borderBottom: '1px solid var(--border-color)' }}>
          <div style={{ maxWidth: 1400, margin: '0 auto', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
            {/* Logo */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
              <div style={{ width: 36, height: 36, background: 'linear-gradient(135deg, #6366f1, #a855f7)', borderRadius: 10, display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '1rem', boxShadow: '0 4px 12px rgba(99,102,241,0.2)' }}>ÔÜí</div>
              <span style={{ fontSize: '1.4rem', fontWeight: 800, letterSpacing: '-0.025em', color: '#f8fafc' }}>SSC FLOW</span>
            </div>

            {/* Central Navigation (Desktop only) */}
            <nav style={{ display: 'none', gap: 32 }}>
              {/* This space is intentionally mostly empty to match the mockup, which has a few subtle links here */}
              {[
                { key: 'hub', label: "Vue d'ensemble" },
                { key: 'analytique', label: 'Analytique' },
                { key: 'fournisseurs', label: 'Fournisseurs' },
              ].map(nav => {
                const isActive = page === nav.key || (nav.key === 'hub' && page === 'dashboard');
                return (
                  <button key={nav.key} onClick={() => setPage(nav.key === 'analytique' ? 'rapports' : nav.key)} style={{
                    background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'inherit',
                    fontSize: '0.875rem', fontWeight: isActive ? 600 : 500,
                    color: isActive ? '#f8fafc' : '#94a3b8',
                    transition: 'color 0.2s', padding: '4px 0',
                  }}>
                    {nav.label}
                  </button>
                );
              })}
            </nav>
            {/* Displaying these links using CSS to match desktop mockup exactly */}
            <nav className="desktop-top-nav" style={{ display: 'flex', gap: 32 }}>
              <button onClick={() => setPage('hub')} style={{ background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'inherit', fontSize: '0.875rem', fontWeight: 600, color: '#f8fafc' }}>Vue d'ensemble</button>
              <button onClick={() => setPage('rapports')} style={{ background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'inherit', fontSize: '0.875rem', fontWeight: 500, color: '#94a3b8' }}>Analytique</button>
              <button onClick={() => setPage('fournisseurs')} style={{ background: 'none', border: 'none', cursor: 'pointer', fontFamily: 'inherit', fontSize: '0.875rem', fontWeight: 500, color: '#94a3b8' }}>Fournisseurs</button>
            </nav>

            {/* Right: Search + Alerts + Avatar */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
              {/* Search */}
              <div style={{ position: 'relative' }}>
                <span style={{ position: 'absolute', left: 12, top: '50%', transform: 'translateY(-50%)', color: '#64748b', fontSize: '0.8rem' }}>­ƒöì</span>
                <input placeholder="Rechercher..." style={{
                  background: 'rgba(30,41,59,0.4)', border: 'none', borderRadius: 9999,
                  paddingLeft: 36, paddingRight: 16, paddingTop: 6, paddingBottom: 6,
                  fontSize: '0.875rem', color: '#f1f5f9', fontFamily: 'inherit',
                  width: 192, outline: 'none', transition: 'width 0.3s',
                }}
                  onFocus={e => e.target.style.width = '256px'}
                  onBlur={e => e.target.style.width = '192px'}
                />
              </div>

              {/* Alert badge */}
              {alertCount > 0 && (
                <button onClick={() => setPage('alertes')} style={{
                  background: 'rgba(239,68,68,0.1)', border: '1px solid rgba(239,68,68,0.2)', borderRadius: 20,
                  padding: '4px 10px', color: '#f87171', fontSize: '0.72rem', fontWeight: 700, cursor: 'pointer',
                  display: 'flex', alignItems: 'center', gap: 4,
                }}>
                  ­ƒöö {alertCount}
                </button>
              )}

              {/* Avatar */}
              <div style={{ position: 'relative' }} ref={profileRef}>
                <div style={{
                  width: 32, height: 32, borderRadius: '50%',
                  border: '1px solid rgba(99,102,241,0.5)', padding: 2,
                  cursor: 'pointer', overflow: 'hidden',
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  background: 'rgba(99,102,241,0.15)', color: '#a5b4fc', fontWeight: 700, fontSize: '0.8rem',
                }}
                  onClick={() => setProfileOpen(!profileOpen)}
                  title={`Connect├®: ${auth.profile?.nom || auth.user?.email}`}
                >
                  {(auth.profile?.nom || auth.user?.email || 'U')[0].toUpperCase()}
                </div>

                {profileOpen && (
                  <div style={{
                    position: 'absolute', top: 44, right: 0, width: 240,
                    background: 'rgba(15,23,42,0.95)', backdropFilter: 'blur(16px)',
                    border: '1px solid rgba(255,255,255,0.1)',
                    borderRadius: 16, boxShadow: '0 12px 40px rgba(0,0,0,0.4)',
                    zIndex: 200, overflow: 'hidden', animation: 'fadeUp 0.15s ease',
                  }}>
                    {(() => {
                      const nom = auth.profile?.nom;
                      const email = auth.user?.email;
                      const isNomEmail = !nom || nom.includes('@');
                      const prenom = isNomEmail ? (email?.split('@')[0] || 'Utilisateur') : nom.split(' ')[0];
                      return (
                        <div style={{ padding: '14px 16px', borderBottom: '1px solid rgba(255,255,255,0.06)', background: 'rgba(255,255,255,0.03)' }}>
                          <div style={{ fontSize: '0.85rem', fontWeight: 700, color: '#f1f5f9' }}>{prenom}</div>
                          <div style={{ fontSize: '0.72rem', color: '#94a3b8', marginTop: 2, overflow: 'hidden', textOverflow: 'ellipsis' }}>{email}</div>
                        </div>
                      );
                    })()}
                    <div style={{ padding: 6 }}>
                      <button onClick={() => { setProfileOpen(false); setPage('parametres'); }} style={{ width: '100%', display: 'flex', alignItems: 'center', gap: 10, padding: '9px 12px', background: 'none', border: 'none', color: '#e2e8f0', fontSize: '0.85rem', cursor: 'pointer', borderRadius: 10, transition: 'background 0.15s' }} onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.05)'} onMouseLeave={e => e.currentTarget.style.background = 'none'}>
                        <span>­ƒæñ</span> Mon Profil
                      </button>
                      <button onClick={() => { setProfileOpen(false); setPwdModalOpen(true); }} style={{ width: '100%', display: 'flex', alignItems: 'center', gap: 10, padding: '9px 12px', background: 'none', border: 'none', color: '#e2e8f0', fontSize: '0.85rem', cursor: 'pointer', borderRadius: 10, transition: 'background 0.15s' }} onMouseEnter={e => e.currentTarget.style.background = 'rgba(255,255,255,0.05)'} onMouseLeave={e => e.currentTarget.style.background = 'none'}>
                        <span>­ƒöæ</span> Mot de passe
                      </button>
                    </div>
                    <div style={{ borderTop: '1px solid rgba(255,255,255,0.06)', padding: 6 }}>
                      <button onClick={auth.logout} style={{ width: '100%', display: 'flex', alignItems: 'center', gap: 10, padding: '9px 12px', background: 'none', border: 'none', color: '#f87171', fontSize: '0.85rem', cursor: 'pointer', borderRadius: 10, transition: 'background 0.15s', fontWeight: 600 }} onMouseEnter={e => e.currentTarget.style.background = 'rgba(239,68,68,0.08)'} onMouseLeave={e => e.currentTarget.style.background = 'none'}>
                        <span>­ƒÜ¬</span> D├®connexion
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>
        </header>

        {/* ÔòÉÔòÉÔòÉ MAIN CONTENT ÔòÉÔòÉÔòÉ */}
        <main style={{ flex: 1, padding: '24px 32px 120px', maxWidth: 1400, margin: '0 auto', width: '100%' }}>
          {/* PASSWORD RESET MODAL */}
          <Modal open={pwdModalOpen} onClose={() => { setPwdModalOpen(false); setPwdMsg(null); }} title="­ƒöÆ Changer de mot de passe" width={400}>
            <p style={{ color: 'var(--text-muted)', fontSize: '0.85rem', marginBottom: 20 }}>
              Vous allez recevoir un email contenant un lien s├®curis├® pour choisir votre nouveau mot de passe.
            </p>
            {pwdMsg && (
              <div style={{ padding: '10px 14px', borderRadius: 10, marginBottom: 16, background: pwdMsg.type === 'success' ? 'rgba(16,185,129,0.08)' : 'rgba(239,68,68,0.08)', color: pwdMsg.type === 'success' ? '#059669' : '#ef4444', fontSize: '0.85rem', border: `1px solid ${pwdMsg.type === 'success' ? 'rgba(16,185,129,0.15)' : 'rgba(239,68,68,0.15)'}` }}>
                {pwdMsg.text}
              </div>
            )}
            <div style={{ display: 'flex', gap: 10, justifyContent: 'flex-end' }}>
              <Btn variant="outline" onClick={() => { setPwdModalOpen(false); setPwdMsg(null); }}>Annuler</Btn>
              <Btn variant="primary" onClick={async () => {
                setPwdMsg(null);
                const res = await auth.resetPassword(auth.user.email);
                if (res.success) setPwdMsg({ type: 'success', text: `Ô£à Lien envoy├® ├á ${auth.user.email} !` });
                else setPwdMsg({ type: 'error', text: `ÔØî Erreur : ${res.error}` });
              }}>Envoyer le lien</Btn>
            </div>
          </Modal>

          {/* PAGE CONTENT */}
          {page === 'hub'          && <Hub store={store} auth={auth} setPage={setPage} />}
          {page === 'dashboard'    && <Dashboard store={store} onNavigate={setPage} />}
          {page === 'produits'     && <Produits store={store} auth={auth} />}
          {page === 'mouvements'   && <Mouvements store={store} auth={auth} />}
          {page === 'scanner'      && <Scanner store={store} />}
          {page === 'alertes'      && <Alertes store={store} onNavigate={setPage} />}
          {page === 'lots'         && <Lots store={store} />}
          {page === 'prix'         && <HistoriquePrix store={store} />}
          {page === 'factures'     && <Facturation store={store} auth={auth} />}
          {page === 'fournisseurs' && <Fournisseurs store={store} auth={auth} />}
          {page === 'commandes'    && <Commandes store={store} auth={auth} />}
          {page === 'clients'      && <Clients store={store} auth={auth} />}
          {page === 'rapports'     && <Rapports store={store} />}
          {page === 'analyses'     && <Analyses store={store} />}
          {page === 'audit'        && <AuditLogs store={store} />}
          {page === 'parametres'   && <Parametres store={store} auth={auth} />}
        </main>

        {/* ÔòÉÔòÉÔòÉ FLOATING BOTTOM NAV ÔòÉÔòÉÔòÉ */}
        <div style={{ position: 'fixed', bottom: 24, left: '50%', transform: 'translateX(-50%)', zIndex: 100 }}>
          <div style={{ 
            display: 'flex', alignItems: 'center', gap: 8, 
            background: 'rgba(30, 41, 59, 0.9)', backdropFilter: 'blur(16px)', 
            padding: '8px 16px', borderRadius: 9999, 
            border: '1px solid rgba(255,255,255,0.1)', boxShadow: '0 10px 40px rgba(0,0,0,0.5)' 
          }}>
            {[
              { id: 'hub', icon: 'M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z', label: 'Accueil' },
              { id: 'commandes', icon: 'M3 3h2l.4 2M7 13h10l4-8H5.4M7 13L5.4 5M7 13l-2.293 2.293c-.63.63-.184 1.707.707 1.707H17m0 0a2 2 0 100 4 2 2 0 000-4zm-8 2a2 2 0 11-4 0 2 2 0 014 0z', label: 'Commandes' },
              { id: 'mouvements', icon: 'M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z', label: 'Historique' },
              { id: 'parametres', icon: 'M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065zM15 12a3 3 0 11-6 0 3 3 0 016 0z', label: 'Syst├¿me' }
            ].map(item => {
              const isActive = page === item.id || (item.id === 'hub' && page === 'dashboard');
              return (
                <button 
                  key={item.id} 
                  onClick={() => setPage(item.id)}
                  style={{
                    display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 4,
                    padding: '8px 16px', borderRadius: 9999,
                    background: isActive ? 'rgba(255,255,255,0.08)' : 'transparent',
                    border: 'none', cursor: 'pointer', transition: 'all 0.2s',
                    color: isActive ? '#f8fafc' : '#94a3b8'
                  }}
                  onMouseEnter={e => { if (!isActive) e.currentTarget.style.color = '#cbd5e1'; }}
                  onMouseLeave={e => { if (!isActive) e.currentTarget.style.color = '#94a3b8'; }}
                >
                  <svg style={{ width: 22, height: 22, fill: 'none', stroke: 'currentColor', strokeWidth: 1.8, strokeLinecap: 'round', strokeLinejoin: 'round' }} viewBox="0 0 24 24">
                    <path d={item.icon} />
                  </svg>
                  <span style={{ fontSize: '0.65rem', fontWeight: isActive ? 600 : 500 }}>{item.label}</span>
                </button>
              );
            })}
          </div>
        </div>
      </div>
      <style>{`
        @media (max-width: 768px) {
          .desktop-top-nav { display: none !important; }
        }
      `}</style>
    </>
  );
}

import React from 'react';

function fmt(n) {
  if (n >= 1000000) return (n / 1000000).toFixed(1) + 'M';
  if (n >= 1000) return (n / 1000).toFixed(0).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return String(n);
}

export default function Hub({ setPage, store, auth }) {
  const { alertes = [], produits = [], mouvements = [], commandes = [], clients = [], fournisseurs = [], factures = [] } = store || {};

  /* ÔöÇÔöÇ Stats ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */
  const totalRevenue = mouvements
    .filter(m => m.type === 'sortie')
    .reduce((s, m) => s + (Number(m.montant) || Number(m.prix_unitaire || 0) * Number(m.quantite || 0)), 0);

  const recentMov = [...mouvements]
    .sort((a, b) => new Date(b.date || 0) - new Date(a.date || 0))
    .slice(0, 3);

  const totalPartners = (clients?.length || 0) + (fournisseurs?.length || 0);

  return (
    <div style={{ padding: '24px 0', maxWidth: 1400, margin: '0 auto', width: '100%', animation: 'fadeIn 0.4s' }}>

      {/* ÔòÉÔòÉÔòÉ GRID LAYOUT (Dark Blue Corporate) ÔòÉÔòÉÔòÉ */}
      <div className="hub-grid">

        {/* COLONNE GAUCHE (Revenu & Catalogue) */}
        <div className="hub-col-left">

          {/* ÔöÇÔöÇ 1. Revenu Total ÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇÔöÇ */}
          <article className="hub-card" onClick={() => setPage('dashboard')} style={{ display: 'flex', flexDirection: 'column' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 24 }}>
              <div>
                <h2 style={{ color: '#94a3b8', fontSize: '0.85rem', fontWeight: 600, textTransform: 'uppercase', letterSpacing: '0.5px', margin: '0 0 8px' }}>Revenu Total</h2>
                <p style={{ fontSize: '2.4rem', fontWeight: 800, letterSpacing: '-0.02em', color: '#f8fafc', margin: 0 }}>{totalRevenue > 0 ? fmt(totalRevenue) + ' F' : '4.2M F'}</p>
              </div>
